INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (321, 0, 125801, "リリ", 40011, 2, 1, 1, 24001, 1, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (322, 0, 126001, "クリア", 40011, 2, 1, 1, 24001, 2, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (323, 0, 126101, "プレシア", 40011, 2, 1, 1, 24001, 3, "んーと。\nこれ、あげる。\nはい");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (324, 0, 125801, "リリ", 40011, 2, 2, 1, 24001, 4, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (325, 0, 126001, "クリア", 40011, 2, 2, 1, 24001, 5, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです");
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (326, 0, 126101, "プレシア", 40011, 2, 2, 1, 24001, 6, "お兄。\nきてくれて、うれしい");
